}"}, {"path": "outline.json", "content": "{
  "act_one": {
    "description": "建立高压环境与人物伪装，引入核心冲突",
    "key_chapters": [
      {
        "chapter_number": 1,
        "chapter_title": "红色的牢笼",
        "core_event": "新婚之夜，两人在布满监听的新房中进行第一次接触，互相试探底线。",
        "emotional_tone": "压抑、悬疑、冷漠",
        "key_scenes": [
          "苏晚独自坐在红色的婚床上，听着窗外的岗哨声",
          "陆骁进门，例行公事般的对话，暗中检查监听设备",
          "两人躺在同一张床上，背对背，各怀鬼胎"
        ]
      }
    ],
    "turning_point": "熄灯后，苏晚在黑暗中闻到了陆骁身上熟悉的硝烟味（或某种特质），伪装出现裂痕。"
  },
  "act_two": {
    "description": "情感在压抑中爆发，通过身体和创伤确认彼此",
    "key_chapters": [
      {
        "chapter_number": 2,
        "chapter_title": "伤疤的语言",
        "core_event": "苏晚发现陆骁背后的枪伤，确认了他的身份，情感防线崩溃。",
        "emotional_tone": "震惊、痛楚、渴望",
        "key_scenes": [
          "陆骁更衣/沐浴，苏晚瞥见狰狞的伤疤",
          "苏晚颤抖着触碰伤疤，陆骁身体僵硬但未拒绝",
          "陆骁谎称是训练伤，但苏晚知道那是为了救她"
        ]
      },
      {
        "chapter_number": 3,
        "chapter_title": "静默的共犯",
        "core_event": "在哨兵巡逻的间隙，两人在极度安静中爆发激烈的性爱，用战场手势交流。",
        "emotional_tone": "疯狂、窒息、暴烈",
        "key_scenes": [
          "窗外手电筒光束扫过，两人在黑暗中死死纠缠",
          "陆骁用手势打出“我爱你”/“杀了我”，苏晚用吻回应",
          "肉体的欢愉与死亡的恐惧交织，达到高潮"
        ]
      }
    ],
    "turning_point": "情事后的短暂温存，两人几乎要开口承认，但理智（生存本能）将他们拉回现实。"
  },
  "act_three": {
    "description": "回归现实，为了保护对方而选择毁灭过去",
    "key_chapters": [
      {
        "chapter_number": 4,
        "chapter_title": "黎明前的审判",
        "core_event": "清晨的电话打破幻象，组织要求汇报新婚情况，陆骁面临抉择。",
        "emotional_tone": "绝望、清醒、决绝",
        "key_scenes": [
          "电话铃声像警报一样响起",
          "陆骁接起电话，苏晚在一旁屏息凝神",
          "陆骁看着苏晚，眼神中流露出最后的诀别"
        ]
      },
      {
        "chapter_number": 5,
        "chapter_title": "未亡人的墓碑",
        "core_event": "陆骁向组织报告“一切正常”，否认了旧情。两人在晨光中扮演回陌生夫妻，完成精神上的永别。",
        "emotional_tone": "死寂、悲剧、余韵",
        "key_scenes": [
          "陆骁整理军装，恢复冷峻面具",
          "苏晚看着结婚证，意识到这是一座合葬的墓碑",
          "陆骁出门，背影消失在岗哨尽头，苏晚流下一滴泪"
        ]
      }
    ]
  }
}"}]}

